<template><section id="github-stats" class="section-space"><div class="container-shell github-layout"><div class="github-copy fade-in-left"><h2>More work on GitHub.</h2><p>The selected case studies are only the beginning. Browse repositories, experiments, and ongoing product work directly in the source.</p><a href="https://github.com/Admiral23kizaru?tab=repositories" target="_blank" rel="noopener noreferrer" class="btn-secondary"><i class="bi bi-github"></i> Explore all repositories</a></div><div class="repo-list fade-in-right"><a v-for="repo in repos" :key="repo.name" :href="repo.html_url" target="_blank" rel="noopener noreferrer"><div><strong>{{repo.name}}</strong><p>{{repo.description||'Source code and project history.'}}</p></div><span>{{repo.language||'Code'}} <i class="bi bi-arrow-up-right"></i></span></a><p v-if="error" class="repo-error">GitHub projects are temporarily unavailable. Use the repository link instead.</p></div></div></section></template>
<script setup>import{ref,onMounted}from'vue';const repos=ref([]);const error=ref(false);onMounted(async()=>{try{const response=await fetch('https://api.github.com/users/Admiral23kizaru/repos?per_page=12&sort=updated');if(!response.ok)throw new Error();const data=await response.json();repos.value=data.filter(repo=>!repo.fork&&repo.name!=='Admiral23kizaru').slice(0,4)}catch{error.value=true}})</script>
<style scoped>.github-layout{display:grid;grid-template-columns:.8fr 1.2fr;gap:clamp(55px,9vw,140px)}.github-copy h2{font-size:clamp(2.7rem,5vw,5rem);line-height:1.02;letter-spacing:-.055em}.github-copy p{color:var(--text-secondary);line-height:1.75;margin:22px 0 30px;max-width:520px}.repo-list{border-top:1px solid var(--line)}.repo-list>a{display:flex;justify-content:space-between;gap:30px;padding:26px 0;border-bottom:1px solid var(--line);transition:.2s ease}.repo-list>a:hover{padding-left:10px}.repo-list strong{font-size:1.08rem}.repo-list p{color:var(--text-secondary);font-size:.86rem;margin-top:5px}.repo-list span{color:var(--text-muted);font-family:var(--font-mono);font-size:.72rem;white-space:nowrap}.repo-error{padding:22px 0;color:var(--text-secondary)}@media(max-width:800px){.github-layout{grid-template-columns:1fr}}</style>
